//#region src/server/metadata-route-cache-policy.ts
function isMetadataResponseCacheable(response) {
	return !(response.headers.get("cache-control")?.toLowerCase() ?? "").split(",").map((directive) => directive.trim().split("=", 1)[0]).some((directive) => directive === "no-cache" || directive === "no-store");
}
//#endregion
export { isMetadataResponseCacheable };
